// === Tab: sketch.js ===
//
// Weekly Creative Coding Challenge Topic 'Vera Molnar'
//
//
// Check the challenge page if you would like to join:
// https://openprocessing.org/curation/78544 
//

// It was fascinating to learn that Vera Molnar was a pioneer
// in generative art. I had a lot of fun experimenting with simple 
// randomness. Thanks Rubén for suggesting this topic!
//
// For this week's challenge, I simply played with various variables,
// such as position offset randomness, line count, and layer count.
// Each variable was subjected to a random transition method, which could
// either be through the position x (xt), the position y (yt), a noise map (noise),
// or just purely random.
//
// I really enjoyed this week!

let parameterTypes = [
  'CONSTANT',
  'XT',
  'YT',
  'NOISE',
  '1-XT',
  '1-YT',
  'RANDOM'
];

async function setup() {
  createCanvas(windowWidth, windowHeight);
  background(10);

  colorMode(HSB);


  let xCount = int(random(6, 24));
  let yCount = int(random(6, 24));

  let shapeType = int(random(0, 2)); // 0: lines, 1: rectangles
  let lineCountMax = int(random(6, 24));
  let layerCountMax = int(random(6, 12));
  let blockLevelMax = int(random(4, 24));

  // a ValueParameter class is use to randomize the transition type
  // it's in object.js, and it's a simple class to understand (I think)
  let paramRandomness = new ValueParameter(0, 1.4, random(parameterTypes));

  // no randomness in line position is an interesting style
  // but the chance is too low with ValueParameter class
  // so make it easier to appear here
  if(random() < 0.1)
    paramRandomness = new ValueParameter(0, 0.0, 'CONSTANT');

  let paramLayersCount = new ValueParameter(1, layerCountMax, random(parameterTypes));
  let paramLineCount = new ValueParameter(2, lineCountMax, random(parameterTypes));
  let paramBlockLevel = new ValueParameter(2, blockLevelMax, random(parameterTypes));

  let fromHue = random(0, 360);
  let fromSat = random(20, 80);
  let fromBri = random(60, 100);
  let fromColor = new NYColor(fromHue, fromSat, fromBri);

  let toHue = processHue(fromHue + random(60, 180));
  let toSat = random(20, 80);
  let toBri = random(60, 100);
  let toColor = new NYColor(toHue, toSat, toBri);

  let canvasPadding = 0.06 * max(width, height);
  let rectWidth = (width - 2 * canvasPadding) / xCount;
  let rectHeight = (height - 2 * canvasPadding) / yCount;

  let blockWidth = min(rectWidth, rectHeight);
  let blockPadding = random(0.05, 0.1) * blockWidth;
  let blockInnerWidth = blockWidth - 2 * blockPadding;

  let xPadding = (width - blockWidth * xCount) / 2;
  let yPadding = (height - blockWidth * yCount) / 2;

  strokeWeight(max(width, height) * 0.001);
  strokeWeight(0.6);

  for (let x = 0; x < xCount; x++) {
    for (let y = 0; y < yCount; y++) {
      let xt = x / xCount;
      let yt = y / yCount;

      let nowX = x * blockWidth + blockPadding + xPadding;
      let nowY = y * blockWidth + blockPadding + yPadding;

      let noiseValue = noise(nowX * 0.006, nowY * 0.006);

      let pointRandomness = paramRandomness.getValue(xt, yt, noiseValue);
      let layersCount = paramLayersCount.getValue(xt, yt, noiseValue);
      let lineCount = paramLineCount.getValue(xt, yt, noiseValue);
      let blockLevel = paramBlockLevel.getValue(xt, yt, noiseValue);

      for (let i = 0; i < layersCount; i++) {
        let layerT = i / (xCount - 1);
        let layerColor = NYLerpColor(fromColor, toColor, layerT);
        layerColor.h = processHue(layerColor.h + 330 * i);

        if (random() < 0.12)
          layerColor.h = processHue(layerColor.h + 180);

        if (random() < 0.06) {
          layerColor.s = 0;
          layerColor.b = 100;
        }

        let newBlock = new MonlarBlock(
          nowX,
          nowY,
          blockInnerWidth,
          blockInnerWidth,
          lineCount,
          pointRandomness,
          layerColor,
          blockLevel,
          shapeType
        );
        newBlock.draw();
      }
    }
  }
}

// async sleep
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

// === Tab: object.js ===
// noprotect
class MonlarBlock {
    constructor(_x, _y, _w, _h, _densityCount, _randomness, _baseColor, _blockLevel, _shapeType = 0) {
        this.x = _x;
        this.y = _y;
        this.w = _w;
        this.h = _h;
        this.randomness = _randomness;
        this.drawCount = _densityCount;
        this.baseColor = _baseColor;

        this.blockLevel = _blockLevel;
        this.segmentsCount = this.blockLevel * 2 - 1;
        this.segmentsWidth = this.w / this.segmentsCount;

        this.shapeType = _shapeType;
    }

    randomEdgePoint() {
        let xIndex = int(random(0, this.segmentsCount + 1));
        let yIndex = int(random(0, this.segmentsCount + 1));

        return [xIndex, yIndex];
    }

    getNearPoint(_xIndex, _yIndex) {

        while (true) {
            let direction = int(random(0, 4));

            // up
            if (direction == 0) {
                if (_yIndex - 1 >= 0) {
                    return [_xIndex, _yIndex - 1];
                }
                else
                    continue;
            }

            // down
            if (direction == 1) {
                if (_yIndex + 1 < this.segmentsCount) {
                    return [_xIndex, _yIndex + 1];
                }
                else
                    continue;
            }

            // left
            if (direction == 2) {
                if (_xIndex - 1 >= 0) {
                    return [_xIndex - 1, _yIndex];
                }
                else
                    continue;
            }

            // right
            if (direction == 3) {
                if (_xIndex + 1 < this.segmentsCount) {
                    return [_xIndex + 1, _yIndex];
                }
                else
                    continue;
            }
        }

    }

    draw() {
        if (this.shapeType == 0)
            this.drawLines();
        else if (this.shapeType == 1)
            this.drawRectangles();
    }

    async drawLines() {
        // draw lines
        let fromCoord = this.randomEdgePoint();
        let toCoord = this.randomEdgePoint();

        let fromX = fromCoord[0] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
        let fromY = fromCoord[1] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
        let toX = toCoord[0] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
        let toY = toCoord[1] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;

        for (let i = 0; i < this.drawCount; i++) {
            push();
            translate(this.x, this.y);

            stroke(this.baseColor.color());
            line(fromX, fromY, toX, toY);

            pop();
            await sleep(1);

            fromCoord = toCoord;
            fromX = toX;
            fromY = toY;

            if (random() < 0.88) {
                toCoord = this.getNearPoint(toCoord[0], toCoord[1]);
            }
            else {
                toCoord = this.randomEdgePoint();
            }

            toX = toCoord[0] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
            toY = toCoord[1] * this.segmentsWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
        }
    }

    async drawRectangles() {
        // draw rectangles
        for (let i = 0; i < this.drawCount; i++) {

            let rectLevel = int(random(0, this.blockLevel));

            let startX = rectLevel * this.segmentsWidth;
            let startY = rectLevel * this.segmentsWidth;

            var rectWidth = this.w - this.segmentsWidth * rectLevel * 2;
            var rectHeight = this.w - this.segmentsWidth * rectLevel * 2;

            let pointAX = startX + random(-this.randomness, this.randomness) * this.segmentsWidth;
            let pointAY = startY + random(-this.randomness, this.randomness) * this.segmentsWidth;

            let pointBX = startX + rectWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
            let pointBY = startY + random(-this.randomness, this.randomness) * this.segmentsWidth;

            let pointCX = startX + rectWidth + random(-this.randomness, this.randomness) * this.segmentsWidth;
            let pointCY = startY + rectHeight + random(-this.randomness, this.randomness) * this.segmentsWidth;

            let pointDX = startX + random(-this.randomness, this.randomness) * this.segmentsWidth;
            let pointDY = startY + rectHeight + random(-this.randomness, this.randomness) * this.segmentsWidth;

            push();
            translate(this.x, this.y);

            stroke(this.baseColor.color());
            line(pointAX, pointAY, pointBX, pointBY);
            line(pointBX, pointBY, pointCX, pointCY);
            line(pointCX, pointCY, pointDX, pointDY);
            line(pointDX, pointDY, pointAX, pointAY);

            pop();

            await sleep(1);
        }
    }
}

class ValueParameter {
    constructor(_valueMin, _valueMax, _type) {
        this.type = _type;
        this.valueMin = _valueMin;
        this.valueMax = _valueMax;
        this.value = 0;

        if (_type == 'CONSTANT') {
            this.value = random(_valueMin, _valueMax);
        }
    }

    getValue(_xt, _yt, _noiseValue) {
        if (this.type == 'CONSTANT')
            return this.value;
        else if (this.type == 'XT')
            return lerp(this.valueMin, this.valueMax, _xt);
        else if (this.type == 'YT')
            return lerp(this.valueMin, this.valueMax, _yt);
        else if (this.type == 'NOISE')
            return lerp(this.valueMin, this.valueMax, _noiseValue);
        else if (this.type == '1-XT')
            return lerp(this.valueMin, this.valueMax, 1.0 - _xt);
        else if (this.type == '1-YT')
            return lerp(this.valueMin, this.valueMax, 1.0 - _yt);
        else if (this.type == 'RANDOM')
            return random(this.valueMin, this.valueMax);
    }
}

class NYColor {
    constructor(_h, _s, _b, _a = 1.0) {
        this.h = _h;
        this.s = _s;
        this.b = _b;
        this.a = _a;

        this.hDiff = 30;
        this.sDiff = 30;
        this.bDiff = 30;
        this.aDiff = 0;
    }

    copy() {
        let newColor = new NYColor(this.h, this.s, this.b, this.a);
        newColor.hDiff = this.hDiff;
        newColor.sDiff = this.sDiff;
        newColor.bDiff = this.bDiff;

        return newColor;
    }

    slightRandomize() {
        this.h += random(-0.5 * this.hDiff, 0.5 * this.hDiff);
        this.s += random(-0.5 * this.sDiff, 0.5 * this.sDiff);
        this.b += random(-0.5 * this.bDiff, 0.5 * this.bDiff);
        this.a += random(-0.5 * this.aDiff, 0.5 * this.aDiff);

        this.h = processHue(this.h);
    }

    newSlightRandomColor() {
        var newColor = this.copy();
        newColor.slightRandomize();
        return newColor;
    }

    color() {
        return color(this.h, this.s, this.b, this.a);
    }

    static newRandomColor(_mainHue) {
        let h = processHue(_mainHue + random(-80, 80));
        let s = random(40, 100);
        let b = random(60, 100);

        return new NYColor(h, s, b);
    }
}




// === Tab: helpers.js ===
function NYLerpHue(_hueA, _hueB, _t) {
  let hueA = _hueA;
  let hueB = _hueB;

  let hueDiff = abs(hueB - hueA);

  if (abs((hueB - 360) - hueA) < hueDiff) {
    hueB -= 360;
  }
  else if (abs((hueB + 360) - hueA) < hueDiff) {
    hueB += 360;
  }
  else {
    return lerp(_hueA, _hueB, _t);
  }

  let resultHue = lerp(hueA, hueB, _t);

  if (resultHue < 0) {
    resultHue += 360;
  }
  else if (resultHue > 360) {
    resultHue -= 360;
  }

  return resultHue;
}

function NYLerpColor(_colorA, _colorB, _t) {
  let _hue = NYLerpHue(_colorA.h, _colorB.h, _t);
  let _sat = lerp(_colorA.s, _colorB.s, _t);
  let _bri = lerp(_colorA.b, _colorB.b, _t);
  let _alpha = lerp(_colorA.a, _colorB.a, _t);

  return new NYColor(_hue, _sat, _bri, _alpha);
}

function NYLerpP5Color(_colorA, _colorB, _t) {
  var hueA = hue(_colorA);
  var hueB = hue(_colorB);

  var hueDiff = abs(hueB - hueA);

  if (abs((hueB - 360) - hueA) < hueDiff) {
    hueB -= 360;
  }
  else if (abs((hueB + 360) - hueA) < hueDiff) {
    hueB += 360;
  }
  else {
    return lerpColor(_colorA, _colorB, _t);
  }

  let satA = saturation(_colorA);
  let briA = brightness(_colorA);
  let alphaA = alpha(_colorA);

  let satB = saturation(_colorB);
  let briB = brightness(_colorB);
  let alphaB = alpha(_colorB);

  var resultHue = lerp(hueA, hueB, _t);
  let resultSat = lerp(satA, satB, _t);
  let resultBri = lerp(briA, briB, _t);
  let resultAlpha = lerp(alphaA, alphaB, _t);

  if (resultHue < 0) {
    resultHue += 360;
  }
  else if (resultHue > 360) {
    resultHue -= 360;
  }

  return color(resultHue, resultSat, resultBri, resultAlpha);
}

function hsbToRgb(_hue, _sat, _bri) {

  // Ensure that the input values are within the valid range
  let inputHue = processHue(_hue);
  let inputSat = Math.max(0, Math.min(100, _sat));
  let inputBri = Math.max(0, Math.min(100, _bri));

  // Convert saturation and brightness to values between 0 and 1
  inputSat /= 100;
  inputBri /= 100;

  // Calculate the chroma (color intensity)
  const chroma = inputSat * inputBri;

  // Calculate the hue sector
  const hueSector = inputHue / 60;

  // Calculate intermediate values
  const x = chroma * (1 - Math.abs((hueSector % 2) - 1));
  const m = inputBri - chroma;

  let r, g, b;

  // Determine the RGB values based on the hue sector
  if (0 <= hueSector && hueSector < 1) {
    r = chroma;
    g = x;
    b = 0;
  } else if (1 <= hueSector && hueSector < 2) {
    r = x;
    g = chroma;
    b = 0;
  } else if (2 <= hueSector && hueSector < 3) {
    r = 0;
    g = chroma;
    b = x;
  } else if (3 <= hueSector && hueSector < 4) {
    r = 0;
    g = x;
    b = chroma;
  } else if (4 <= hueSector && hueSector < 5) {
    r = x;
    g = 0;
    b = chroma;
  } else {
    r = chroma;
    g = 0;
    b = x;
  }

  // Adjust the RGB values by adding the m (brightness minus chroma)
  r = (r + m) * 255;
  g = (g + m) * 255;
  b = (b + m) * 255;

  // Ensure the RGB values are within the valid range (0 - 255)
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));

  return {
    r: Math.round(r),
    g: Math.round(g),
    b: Math.round(b),
  };
}

function lchToRgb(lightness, chroma, hue) {
  // Ensure that the input values are within the valid range
  lightness = Math.max(0, Math.min(100, lightness));
  chroma = Math.max(0, Math.min(132, chroma));
  hue = (hue % 360 + 360) % 360; // Ensure hue is within the range 0-359

  // Convert chroma and lightness to values between 0 and 1
  chroma /= 132;
  lightness /= 100;

  // Calculate the angle in radians for the hue
  const hueRadians = (hue / 360) * (2 * Math.PI);

  // Calculate the intermediate values
  var x = chroma * Math.cos(hueRadians);
  const y = chroma * Math.sin(hueRadians);

  // Calculate the temporary values
  const temp1 = lightness * 2 - 1;
  const temp2 = chroma * (1 - Math.abs(2 * lightness - 1));

  // Calculate the RGB values
  var r, g, b;

  if (hue >= 0 && hue < 120) {
    r = temp2;
    g = temp1;
    b = 0;
  } else if (hue >= 120 && hue < 240) {
    r = 0;
    g = temp2;
    b = temp1;
  } else {
    r = temp1;
    g = 0;
    b = temp2;
  }

  // Adjust the RGB values
  r = (r + chroma) * 255;
  g = (g + chroma) * 255;
  b = (b + chroma) * 255;

  // Ensure the RGB values are within the valid range (0 - 255)
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));

  return {
    r: Math.round(r),
    g: Math.round(g),
    b: Math.round(b),
  };
}

function processHue(_hue) {
  let result = (_hue % 360 + 360) % 360;
  return result;
}

// get angle between two points and return in degrees
function getAngle(_x1, _y1, _x2, _y2) {
  let xDiff = _x2 - _x1;
  let yDiff = _y2 - _y1;
  return atan2(yDiff, xDiff) * 180 / PI + 90;
}

